
-- Update all 16 email templates to use the Ellosuit SVG logo as base64 data URL
-- The SVG has white text on transparent background, perfect for dark headers

UPDATE email_templates
SET html_content = regexp_replace(
  html_content,
  '<img[^>]*ellosuit[^>]*>',
  '<img src="data:image/svg+xml;base64," alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;">',
  'gi'
)
WHERE company_id = '60008c43-e536-482d-a090-91904de57534';
